using ContosoUniversity.Data;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests.Helpers
{
    public static class TestDbContextFactory
    {
        public static SchoolContext Create(string? dbName = null)
        {
            dbName ??= Guid.NewGuid().ToString();
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: dbName)
                .Options;
            var context = new SchoolContext(options);
            context.Database.EnsureCreated();
            return context;
        }
    }
}

using ContosoUniversity.Models;
using ContosoUniversity.Services;

namespace ContosoUniversity.Tests
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _service;

        public NotificationServiceTests()
        {
            _service = new NotificationService();
            // Drain the static queue to isolate tests
            while (_service.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            // Drain queue after each test to avoid cross-test contamination
            while (_service.ReceiveNotification() != null) { }
            _service.Dispose();
        }

        [Fact]
        public void SendNotification_WithValidInputs_CreatesNotificationWithCorrectProperties()
        {
            // Arrange & Act
            _service.SendNotification("Course", "101", EntityOperation.CREATE, "admin");
            var notification = _service.ReceiveNotification();

            // Assert
            Assert.NotNull(notification);
            Assert.Equal("Course", notification.EntityType);
            Assert.Equal("101", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Equal("admin", notification.CreatedBy);
            Assert.False(notification.IsRead);
            Assert.True(notification.CreatedAt <= DateTime.Now);
            Assert.True(notification.CreatedAt > DateTime.Now.AddSeconds(-5));
        }

        [Fact]
        public void SendNotification_WithoutUserName_DefaultsToSystem()
        {
            // Arrange & Act
            _service.SendNotification("Course", "101", EntityOperation.CREATE);
            var notification = _service.ReceiveNotification();

            // Assert
            Assert.NotNull(notification);
            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_WithDisplayName_GeneratesNamedMessage()
        {
            // Arrange & Act
            _service.SendNotification("Course", "101", "Chemistry", EntityOperation.CREATE, "admin");
            var notification = _service.ReceiveNotification();

            // Assert
            Assert.NotNull(notification);
            Assert.Equal("New Course 'Chemistry' has been created", notification.Message);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_GeneratesIdBasedMessage()
        {
            // Arrange & Act
            _service.SendNotification("Course", "123", EntityOperation.CREATE, "admin");
            var notification = _service.ReceiveNotification();

            // Assert
            Assert.NotNull(notification);
            Assert.Equal("New Course (ID: 123) has been created", notification.Message);
        }

        [Theory]
        [InlineData(EntityOperation.CREATE, "New Course 'Algebra' has been created")]
        [InlineData(EntityOperation.UPDATE, "Course 'Algebra' has been updated")]
        [InlineData(EntityOperation.DELETE, "Course 'Algebra' has been deleted")]
        public void SendNotification_DifferentOperations_GeneratesCorrectMessages(
            EntityOperation operation, string expectedMessage)
        {
            // Arrange & Act
            _service.SendNotification("Course", "1", "Algebra", operation, "admin");
            var notification = _service.ReceiveNotification();

            // Assert
            Assert.NotNull(notification);
            Assert.Equal(expectedMessage, notification.Message);
        }

        [Fact]
        public void SendNotification_CreateWithoutDisplayName_GeneratesIdMessage()
        {
            // Arrange & Act
            _service.SendNotification("Student", "42", EntityOperation.UPDATE);
            var notification = _service.ReceiveNotification();

            // Assert
            Assert.NotNull(notification);
            Assert.Equal("Student (ID: 42) has been updated", notification.Message);
        }

        [Fact]
        public void ReceiveNotification_WhenEmpty_ReturnsNull()
        {
            // Act
            var notification = _service.ReceiveNotification();

            // Assert
            Assert.Null(notification);
        }

        [Fact]
        public void ReceiveNotification_MultipleItems_ReturnsFIFOOrder()
        {
            // Arrange
            _service.SendNotification("Course", "1", "First", EntityOperation.CREATE);
            _service.SendNotification("Course", "2", "Second", EntityOperation.UPDATE);
            _service.SendNotification("Course", "3", "Third", EntityOperation.DELETE);

            // Act & Assert
            var first = _service.ReceiveNotification();
            Assert.NotNull(first);
            Assert.Contains("First", first.Message);

            var second = _service.ReceiveNotification();
            Assert.NotNull(second);
            Assert.Contains("Second", second.Message);

            var third = _service.ReceiveNotification();
            Assert.NotNull(third);
            Assert.Contains("Third", third.Message);

            Assert.Null(_service.ReceiveNotification());
        }

        [Fact]
        public void SendNotification_QueueCapAt500_DropsOldestWhenExceeded()
        {
            // Arrange - fill the queue beyond the 500 cap
            for (int i = 0; i < 505; i++)
            {
                _service.SendNotification("Item", i.ToString(), $"Item{i}", EntityOperation.CREATE);
            }

            // Act - dequeue all and collect
            var notifications = new List<Notification>();
            Notification? n;
            while ((n = _service.ReceiveNotification()) != null)
            {
                notifications.Add(n);
            }

            // Assert - should have at most 500 items, oldest should be dropped
            Assert.True(notifications.Count <= 500);
            // The last item enqueued should still be present
            Assert.Contains(notifications, x => x.Message.Contains("Item504"));
        }

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            // Act & Assert - MarkAsRead is a no-op, should not throw
            var exception = Record.Exception(() => _service.MarkAsRead(999));
            Assert.Null(exception);
        }

        [Fact]
        public void Dispose_DoesNotThrow()
        {
            // Arrange
            var service = new NotificationService();

            // Act & Assert
            var exception = Record.Exception(() => service.Dispose());
            Assert.Null(exception);
        }

        [Fact]
        public void SendNotification_OperationStoredAsString()
        {
            // Arrange & Act
            _service.SendNotification("Department", "5", EntityOperation.DELETE, "teacher");
            var notification = _service.ReceiveNotification();

            // Assert
            Assert.NotNull(notification);
            Assert.Equal("DELETE", notification.Operation);
        }

        [Fact]
        public void SendNotification_IsReadDefaultsFalse()
        {
            // Arrange & Act
            _service.SendNotification("Course", "1", EntityOperation.CREATE);
            var notification = _service.ReceiveNotification();

            // Assert
            Assert.NotNull(notification);
            Assert.False(notification.IsRead);
        }
    }
}

namespace ContosoUniversity.Tests
