using ContosoUniversity.Data;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests.Helpers
{
    public static class TestDbContextFactory
    {
        public static SchoolContext Create(string? dbName = null)
        {
            dbName ??= Guid.NewGuid().ToString();
            var options = new DbContextOptionsBuilder<SchoolContext>()
                .UseInMemoryDatabase(databaseName: dbName)
                .Options;
            var context = new SchoolContext(options);
            context.Database.EnsureCreated();
            return context;
        }
    }
}

using ContosoUniversity.Models;

namespace ContosoUniversity.Tests
{
    public class ErrorViewModelTests
    {
        [Fact]
        public void ShowRequestId_NonEmptyRequestId_ReturnsTrue()
        {
            var model = new ErrorViewModel { RequestId = "abc123" };

            Assert.True(model.ShowRequestId);
        }

        [Fact]
        public void ShowRequestId_NullRequestId_ReturnsFalse()
        {
            var model = new ErrorViewModel { RequestId = null };

            Assert.False(model.ShowRequestId);
        }

        [Fact]
        public void ShowRequestId_EmptyRequestId_ReturnsFalse()
        {
            var model = new ErrorViewModel { RequestId = "" };

            Assert.False(model.ShowRequestId);
        }

        [Theory]
        [InlineData("request-1", true)]
        [InlineData("  ", true)]
        [InlineData("", false)]
        [InlineData(null, false)]
        public void ShowRequestId_VariousValues_ReturnsExpected(string? requestId, bool expected)
        {
            var model = new ErrorViewModel { RequestId = requestId! };

            Assert.Equal(expected, model.ShowRequestId);
        }
    }
}

using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.Rendering;
using Microsoft.Extensions.Logging;
using Moq;

namespace ContosoUniversity.Tests
{
    public class CoursesControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly Mock<IWebHostEnvironment> _mockEnv;
        private readonly Mock<ILogger<CoursesController>> _mockLogger;
        private readonly CoursesController _controller;

        public CoursesControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _mockEnv = new Mock<IWebHostEnvironment>();
            _mockEnv.Setup(e => e.WebRootPath).Returns((string?)null);
            _mockEnv.Setup(e => e.ContentRootPath).Returns(Path.Combine(Directory.GetCurrentDirectory(), "testroot"));
            _mockLogger = new Mock<ILogger<CoursesController>>();
            _controller = new CoursesController(_context, _mockEnv.Object, _mockLogger.Object);
        }

        public void Dispose()
        {
            _context.Dispose();
            _controller.Dispose();
        }

        private Department SeedDepartment(string name = "Engineering")
        {
            var dept = new Department
            {
                Name = name,
                Budget = 100000m,
                StartDate = new DateTime(2020, 1, 1)
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();
            return dept;
        }

        private Course SeedCourse(int courseId, string title, int departmentId)
        {
            var course = new Course
            {
                CourseID = courseId,
                Title = title,
                Credits = 3,
                DepartmentID = departmentId
            };
            _context.Courses.Add(course);
            _context.SaveChanges();
            return course;
        }

        private static Mock<IFormFile> CreateMockFile(string fileName, long length)
        {
            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns(fileName);
            mockFile.Setup(f => f.Length).Returns(length);
            mockFile.Setup(f => f.CopyTo(It.IsAny<Stream>()));
            return mockFile;
        }

        // ==================== Index ====================

        [Fact]
        public void Index_ReturnsViewResult_WithListOfCourses()
        {
            var dept = SeedDepartment();
            SeedCourse(1001, "Calculus", dept.DepartmentID);
            SeedCourse(1002, "Physics", dept.DepartmentID);

            var result = _controller.Index();

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<List<Course>>(viewResult.Model);
            Assert.Equal(2, model.Count);
        }

        [Fact]
        public void Index_IncludesDepartment()
        {
            var dept = SeedDepartment("Science");
            SeedCourse(2001, "Biology", dept.DepartmentID);

            var result = _controller.Index();

            var viewResult = Assert.IsType<ViewResult>(result);
            var courses = Assert.IsAssignableFrom<List<Course>>(viewResult.Model);
            Assert.Equal("Science", courses[0].Department.Name);
        }

        [Fact]
        public void Index_EmptyDatabase_ReturnsEmptyList()
        {
            var result = _controller.Index();

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<List<Course>>(viewResult.Model);
            Assert.Empty(model);
        }

        // ==================== Details ====================

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithCourse()
        {
            var dept = SeedDepartment();
            SeedCourse(3001, "Algebra", dept.DepartmentID);

            var result = _controller.Details(3001);

            var viewResult = Assert.IsType<ViewResult>(result);
            var course = Assert.IsType<Course>(viewResult.Model);
            Assert.Equal("Algebra", course.Title);
            Assert.Equal("Engineering", course.Department.Name);
        }

        [Fact]
        public void Details_InvalidId_ThrowsInvalidOperationException()
        {
            SeedDepartment();

            Assert.Throws<InvalidOperationException>(() => _controller.Details(9999));
        }

        // ==================== Create GET ====================

        [Fact]
        public void Create_GET_ReturnsViewWithNewCourse()
        {
            SeedDepartment();

            var result = _controller.Create();

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.IsType<Course>(viewResult.Model);
        }

        [Fact]
        public void Create_GET_SetsViewBagDepartmentID()
        {
            var dept = SeedDepartment("Math");

            var result = _controller.Create();

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.NotNull(viewResult.ViewData["DepartmentID"]);
            var selectList = Assert.IsType<SelectList>(viewResult.ViewData["DepartmentID"]);
            Assert.Single(selectList);
        }

        // ==================== Create POST ====================

        [Fact]
        public void Create_POST_ValidModelNoFile_AddsCourseAndRedirects()
        {
            var dept = SeedDepartment();
            var course = new Course
            {
                CourseID = 4001,
                Title = "Chemistry",
                Credits = 4,
                DepartmentID = dept.DepartmentID
            };

            var result = _controller.Create(course, null!);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Single(_context.Courses);
            Assert.Equal("Chemistry", _context.Courses.First().Title);
        }

        [Fact]
        public void Create_POST_InvalidExtension_AddsModelError()
        {
            var dept = SeedDepartment();
            var course = new Course { CourseID = 4002, Title = "Test", Credits = 3, DepartmentID = dept.DepartmentID };
            var mockFile = CreateMockFile("doc.pdf", 1024);

            var result = _controller.Create(course, mockFile.Object);

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.False(_controller.ModelState.IsValid);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Theory]
        [InlineData(".pdf")]
        [InlineData(".exe")]
        [InlineData(".txt")]
        [InlineData(".doc")]
        public void Create_POST_DisallowedExtension_AddsModelError(string ext)
        {
            var dept = SeedDepartment();
            var course = new Course { CourseID = 4003, Title = "Test", Credits = 3, DepartmentID = dept.DepartmentID };
            var mockFile = CreateMockFile($"file{ext}", 1024);

            var result = _controller.Create(course, mockFile.Object);

            Assert.IsType<ViewResult>(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Create_POST_FileTooLarge_AddsModelError()
        {
            var dept = SeedDepartment();
            var course = new Course { CourseID = 4004, Title = "Test", Credits = 3, DepartmentID = dept.DepartmentID };
            var mockFile = CreateMockFile("image.jpg", 6 * 1024 * 1024);

            var result = _controller.Create(course, mockFile.Object);

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
            var errors = _controller.ModelState["teachingMaterialImage"]!.Errors;
            Assert.Contains("5MB", errors[0].ErrorMessage);
        }

        [Fact]
        public void Create_POST_FileUploadException_AddsModelError()
        {
            var dept = SeedDepartment();
            var course = new Course { CourseID = 4005, Title = "Test", Credits = 3, DepartmentID = dept.DepartmentID };
            var mockFile = CreateMockFile("image.png", 1024);
            mockFile.Setup(f => f.CopyTo(It.IsAny<Stream>())).Throws(new IOException("Disk full"));

            // Set a non-existent webroot to trigger an exception during Directory.CreateDirectory or File.Create
            _mockEnv.Setup(e => e.ContentRootPath).Returns(Path.Combine(Directory.GetCurrentDirectory(), "testroot_create"));

            var result = _controller.Create(course, mockFile.Object);

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Create_POST_InvalidModelState_ReturnsViewWithCourseAndViewBag()
        {
            var dept = SeedDepartment();
            var course = new Course { CourseID = 4006, Title = "Test", Credits = 3, DepartmentID = dept.DepartmentID };
            _controller.ModelState.AddModelError("Title", "Required");

            var result = _controller.Create(course, null!);

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.Equal(course, viewResult.Model);
            Assert.NotNull(viewResult.ViewData["DepartmentID"]);
        }

        [Theory]
        [InlineData(".jpg")]
        [InlineData(".jpeg")]
        [InlineData(".png")]
        [InlineData(".gif")]
        [InlineData(".bmp")]
        public void Create_POST_ValidImageExtension_DoesNotAddExtensionError(string ext)
        {
            var dept = SeedDepartment();
            var course = new Course { CourseID = 5000 + ext.GetHashCode(), Title = "Test", Credits = 3, DepartmentID = dept.DepartmentID };
            var mockFile = CreateMockFile($"image{ext}", 1024);

            // The file upload will fail due to test env but won't fail on extension validation
            // We just check that the extension-specific error is not added
            _controller.Create(course, mockFile.Object);

            if (_controller.ModelState.ContainsKey("teachingMaterialImage"))
            {
                var errors = _controller.ModelState["teachingMaterialImage"]!.Errors;
                Assert.DoesNotContain(errors, e => e.ErrorMessage.Contains("valid image file"));
            }
        }

        // ==================== Edit GET ====================

        [Fact]
        public void Edit_GET_NullId_ReturnsBadRequest()
        {
            var result = _controller.Edit((int?)null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Edit_GET_InvalidId_ReturnsNotFound()
        {
            var result = _controller.Edit(9999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Edit_GET_ValidId_ReturnsViewWithCourseAndViewBag()
        {
            var dept = SeedDepartment();
            SeedCourse(5001, "History", dept.DepartmentID);

            var result = _controller.Edit(5001);

            var viewResult = Assert.IsType<ViewResult>(result);
            var course = Assert.IsType<Course>(viewResult.Model);
            Assert.Equal("History", course.Title);
            Assert.NotNull(viewResult.ViewData["DepartmentID"]);
        }

        // ==================== Edit POST ====================

        [Fact]
        public void Edit_POST_ValidModelNoFile_UpdatesAndRedirects()
        {
            var dept = SeedDepartment();
            SeedCourse(6001, "OldTitle", dept.DepartmentID);
            // Detach the tracked entity so we can attach a modified one
            _context.ChangeTracker.Clear();

            var updatedCourse = new Course
            {
                CourseID = 6001,
                Title = "NewTitle",
                Credits = 4,
                DepartmentID = dept.DepartmentID
            };

            var result = _controller.Edit(updatedCourse, null!);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            _context.ChangeTracker.Clear();
            Assert.Equal("NewTitle", _context.Courses.Find(6001)!.Title);
        }

        [Fact]
        public void Edit_POST_InvalidExtension_AddsModelError()
        {
            var dept = SeedDepartment();
            SeedCourse(6002, "Test", dept.DepartmentID);
            _context.ChangeTracker.Clear();

            var course = new Course { CourseID = 6002, Title = "Test", Credits = 3, DepartmentID = dept.DepartmentID };
            var mockFile = CreateMockFile("doc.txt", 1024);

            var result = _controller.Edit(course, mockFile.Object);

            Assert.IsType<ViewResult>(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Edit_POST_FileTooLarge_AddsModelError()
        {
            var dept = SeedDepartment();
            SeedCourse(6003, "Test", dept.DepartmentID);
            _context.ChangeTracker.Clear();

            var course = new Course { CourseID = 6003, Title = "Test", Credits = 3, DepartmentID = dept.DepartmentID };
            var mockFile = CreateMockFile("image.jpg", 10 * 1024 * 1024);

            var result = _controller.Edit(course, mockFile.Object);

            Assert.IsType<ViewResult>(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Edit_POST_InvalidModelState_ReturnsViewWithCourse()
        {
            var dept = SeedDepartment();
            var course = new Course { CourseID = 6004, Title = "Test", Credits = 3, DepartmentID = dept.DepartmentID };
            _controller.ModelState.AddModelError("Title", "Required");

            var result = _controller.Edit(course, null!);

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.Equal(course, viewResult.Model);
            Assert.NotNull(viewResult.ViewData["DepartmentID"]);
        }

        // ==================== Delete GET ====================

        [Fact]
        public void Delete_GET_NullId_ReturnsBadRequest()
        {
            var result = _controller.Delete(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Delete_GET_ValidId_ReturnsViewWithCourse()
        {
            var dept = SeedDepartment();
            SeedCourse(7001, "Art", dept.DepartmentID);

            var result = _controller.Delete(7001);

            var viewResult = Assert.IsType<ViewResult>(result);
            var course = Assert.IsType<Course>(viewResult.Model);
            Assert.Equal("Art", course.Title);
        }

        [Fact]
        public void Delete_GET_InvalidId_ThrowsInvalidOperationException()
        {
            Assert.Throws<InvalidOperationException>(() => _controller.Delete(9999));
        }

        // ==================== DeleteConfirmed POST ====================

        [Fact]
        public void DeleteConfirmed_ValidId_RemovesCourseAndRedirects()
        {
            var dept = SeedDepartment();
            SeedCourse(8001, "Music", dept.DepartmentID);

            var result = _controller.DeleteConfirmed(8001);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Empty(_context.Courses);
        }

        [Fact]
        public void DeleteConfirmed_CourseWithNoImage_DoesNotThrow()
        {
            var dept = SeedDepartment();
            SeedCourse(8002, "PE", dept.DepartmentID);

            var result = _controller.DeleteConfirmed(8002);

            Assert.IsType<RedirectToActionResult>(result);
            Assert.Null(_context.Courses.Find(8002));
        }
    }
}

using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.Rendering;

namespace ContosoUniversity.Tests
{
    public class DepartmentsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly DepartmentsController _controller;

        public DepartmentsControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _controller = new DepartmentsController(_context);
        }

        public void Dispose()
        {
            _context.Dispose();
            _controller.Dispose();
        }

        private Department SeedDepartment(string name = "Engineering", decimal budget = 100000m)
        {
            var dept = new Department
            {
                Name = name,
                Budget = budget,
                StartDate = new DateTime(2020, 1, 1)
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();
            return dept;
        }

        private Instructor SeedInstructor(string lastName = "Smith", string firstName = "John")
        {
            var instructor = new Instructor
            {
                LastName = lastName,
                FirstMidName = firstName,
                HireDate = new DateTime(2015, 8, 1),
                CourseAssignments = new List<CourseAssignment>()
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();
            return instructor;
        }

        // ==================== Index ====================

        [Fact]
        public void Index_ReturnsViewResult_WithListOfDepartments()
        {
            SeedDepartment("Engineering");
            SeedDepartment("Science");

            var result = _controller.Index();

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<List<Department>>(viewResult.Model);
            Assert.Equal(2, model.Count);
        }

        [Fact]
        public void Index_IncludesAdministrator()
        {
            var instructor = SeedInstructor();
            var dept = new Department
            {
                Name = "Math",
                Budget = 50000m,
                StartDate = new DateTime(2020, 1, 1),
                InstructorID = instructor.ID
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();

            var result = _controller.Index();

            var viewResult = Assert.IsType<ViewResult>(result);
            var departments = Assert.IsAssignableFrom<List<Department>>(viewResult.Model);
            Assert.Equal("Smith", departments[0].Administrator?.LastName);
        }

        [Fact]
        public void Index_EmptyDatabase_ReturnsEmptyList()
        {
            var result = _controller.Index();

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsAssignableFrom<List<Department>>(viewResult.Model);
            Assert.Empty(model);
        }

        // ==================== Details ====================

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithDepartment()
        {
            var dept = SeedDepartment("Physics");

            var result = _controller.Details(dept.DepartmentID);

            var viewResult = Assert.IsType<ViewResult>(result);
            var model = Assert.IsType<Department>(viewResult.Model);
            Assert.Equal("Physics", model.Name);
        }

        [Fact]
        public void Details_InvalidId_ReturnsNotFound()
        {
            var result = _controller.Details(9999);

            Assert.IsType<NotFoundResult>(result);
        }

        // ==================== Create GET ====================

        [Fact]
        public void Create_GET_ReturnsView()
        {
            SeedInstructor();

            var result = _controller.Create();

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.Null(viewResult.Model);
        }

        [Fact]
        public void Create_GET_SetsViewBagInstructorID()
        {
            SeedInstructor("Doe", "Jane");

            var result = _controller.Create();

            var viewResult = Assert.IsType<ViewResult>(result);
            Assert.NotNull(viewResult.ViewData["InstructorID"]);
            var selectList = Assert.IsType<SelectList>(viewResult.ViewData["InstructorID"]);
            Assert.Single(selectList);
        }

        // ==================== Create POST ====================

        [Fact]
        public void Create_POST_ValidModel_AddsDepartmentAndRedirects()
        {
            SeedInstructor();
            var dept = new Department
            {
                Name = "History",
                Budget = 75000m,
                StartDate = new DateTime(2021, 9, 1)
            };

            var result = _controller.Create(dept);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Single(_context.Departments);
            Assert.Equal("History", _context.Departments.First().Name);
        }

        [Fact]
        public void Create_POST_InvalidModelState_ReturnsViewWithDepartment()
