        [Fact]
        public void Edit_GET_PopulatesAssignedCourseData()
        {
            var dept = SeedDepartment();
            var course1 = SeedCourse(4002, "Art", dept.DepartmentID);
            var course2 = SeedCourse(4003, "Drama", dept.DepartmentID);
            var instructor = SeedInstructor("Irving", "Ian");
            SeedCourseAssignment(instructor.ID, course1.CourseID);

            var result = _controller.Edit(instructor.ID);

            var viewResult = Assert.IsType<ViewResult>(result);
            var courseData = Assert.IsAssignableFrom<List<AssignedCourseData>>(viewResult.ViewData["Courses"]);
