using System;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Xunit;

namespace ContosoUniversity.Tests
{
    public class NotificationsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly NotificationsController _controller;

        public NotificationsControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _controller = new NotificationsController(_context);
            _controller.ControllerContext = new ControllerContext
            {
                HttpContext = new DefaultHttpContext()
            };
            // Drain static queue to isolate tests
            DrainNotificationQueue();
        }

        public void Dispose()
        {
            DrainNotificationQueue();
            _controller.Dispose();
            _context.Dispose();
        }

        private void DrainNotificationQueue()
        {
            var svc = new NotificationService();
            while (svc.ReceiveNotification() != null) { }
            svc.Dispose();
        }

        private void EnqueueNotifications(int count)
        {
            var svc = new NotificationService();
            for (int i = 0; i < count; i++)
            {
                svc.SendNotification("Student", i.ToString(), $"Student {i}", EntityOperation.CREATE, "TestUser");
            }
            svc.Dispose();
        }

        #region GetNotifications

        [Fact]
        public void GetNotifications_NoNotifications_ReturnsSuccessWithEmptyList()
        {
            var result = _controller.GetNotifications();

            dynamic value = result.Value!;
            bool success = (bool)value.GetType().GetProperty("success")!.GetValue(value);
            int count = (int)value.GetType().GetProperty("count")!.GetValue(value);

            Assert.True(success);
            Assert.Equal(0, count);
        }

        [Fact]
        public void GetNotifications_WithNotifications_ReturnsDrainedNotifications()
        {
            EnqueueNotifications(3);

            var result = _controller.GetNotifications();

            dynamic value = result.Value!;
            bool success = (bool)value.GetType().GetProperty("success")!.GetValue(value);
            int count = (int)value.GetType().GetProperty("count")!.GetValue(value);

            Assert.True(success);
            Assert.Equal(3, count);
        }

        [Fact]
        public void GetNotifications_MoreThan10_LimitsTo10()
        {
            EnqueueNotifications(15);

            var result = _controller.GetNotifications();

            dynamic value = result.Value!;
            int count = (int)value.GetType().GetProperty("count")!.GetValue(value);

            Assert.Equal(10, count);
        }

        [Fact]
        public void GetNotifications_CalledTwice_SecondCallGetsRemaining()
        {
            EnqueueNotifications(15);

            _controller.GetNotifications(); // drains first 10
            var result = _controller.GetNotifications();

            dynamic value = result.Value!;
            int count = (int)value.GetType().GetProperty("count")!.GetValue(value);

            Assert.Equal(5, count);
        }

        [Fact]
        public void GetNotifications_NotificationsContainCorrectData()
        {
            EnqueueNotifications(1);

            var result = _controller.GetNotifications();

            dynamic value = result.Value!;
            var notifications = value.GetType().GetProperty("notifications")!.GetValue(value);
            var list = new System.Collections.Generic.List<Notification>((System.Collections.Generic.IEnumerable<Notification>)notifications);

            Assert.Single(list);
            Assert.Equal("Student", list[0].EntityType);
            Assert.Equal("0", list[0].EntityId);
            Assert.Equal("CREATE", list[0].Operation);
            Assert.Contains("Student 0", list[0].Message);
        }

        #endregion

        #region MarkAsRead

        [Fact]
        public void MarkAsRead_ValidId_ReturnsSuccess()
        {
            var result = _controller.MarkAsRead(1);

            dynamic value = result.Value!;
            bool success = (bool)value.GetType().GetProperty("success")!.GetValue(value);

            Assert.True(success);
        }

        [Fact]
        public void MarkAsRead_AnyId_ReturnsSuccessTrue()
        {
            // MarkAsRead is a no-op in the in-memory implementation, always succeeds
            var result = _controller.MarkAsRead(999);

            dynamic value = result.Value!;
            bool success = (bool)value.GetType().GetProperty("success")!.GetValue(value);

            Assert.True(success);
        }

        #endregion

        #region Index

        [Fact]
        public void Index_ReturnsViewResult()
        {
            var result = _controller.Index();

            Assert.IsType<ViewResult>(result);
        }

        #endregion
    }
}

