using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;

namespace ContosoUniversity.Tests
{
    public class DbInitializerTests
    {
        private SchoolContext CreateAndSeed()
        {
            var context = TestDbContextFactory.Create();
            DbInitializer.Initialize(context);
            return context;
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsStudents()
        {
            using var context = CreateAndSeed();

            var students = context.Students.ToList();
            Assert.Equal(8, students.Count);
            Assert.Contains(students, s => s.LastName == "Alexander" && s.FirstMidName == "Carson");
            Assert.Contains(students, s => s.LastName == "Alonso" && s.FirstMidName == "Meredith");
            Assert.Contains(students, s => s.LastName == "Anand" && s.FirstMidName == "Arturo");
            Assert.Contains(students, s => s.LastName == "Barzdukas" && s.FirstMidName == "Gytis");
            Assert.Contains(students, s => s.LastName == "Li" && s.FirstMidName == "Yan");
            Assert.Contains(students, s => s.LastName == "Justice" && s.FirstMidName == "Peggy");
            Assert.Contains(students, s => s.LastName == "Norman" && s.FirstMidName == "Laura");
            Assert.Contains(students, s => s.LastName == "Olivetto" && s.FirstMidName == "Nino");
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsInstructors()
        {
            using var context = CreateAndSeed();

            var instructors = context.Instructors.ToList();
            Assert.Equal(5, instructors.Count);
            Assert.Contains(instructors, i => i.LastName == "Abercrombie");
            Assert.Contains(instructors, i => i.LastName == "Fakhouri");
            Assert.Contains(instructors, i => i.LastName == "Harui");
            Assert.Contains(instructors, i => i.LastName == "Kapoor");
            Assert.Contains(instructors, i => i.LastName == "Zheng");
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsDepartments()
        {
            using var context = CreateAndSeed();

            var departments = context.Departments.ToList();
            Assert.Equal(4, departments.Count);
            Assert.Contains(departments, d => d.Name == "English");
            Assert.Contains(departments, d => d.Name == "Mathematics");
            Assert.Contains(departments, d => d.Name == "Engineering");
            Assert.Contains(departments, d => d.Name == "Economics");
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsCourses()
        {
            using var context = CreateAndSeed();

            var courses = context.Courses.ToList();
            Assert.Equal(7, courses.Count);
            Assert.Contains(courses, c => c.Title == "Chemistry" && c.Credits == 3 && c.CourseID == 1050);
            Assert.Contains(courses, c => c.Title == "Microeconomics" && c.Credits == 3 && c.CourseID == 4022);
            Assert.Contains(courses, c => c.Title == "Macroeconomics" && c.Credits == 3 && c.CourseID == 4041);
            Assert.Contains(courses, c => c.Title == "Calculus" && c.Credits == 4 && c.CourseID == 1045);
            Assert.Contains(courses, c => c.Title == "Trigonometry" && c.Credits == 4 && c.CourseID == 3141);
            Assert.Contains(courses, c => c.Title == "Composition" && c.Credits == 3 && c.CourseID == 2021);
            Assert.Contains(courses, c => c.Title == "Literature" && c.Credits == 4 && c.CourseID == 2042);
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsOfficeAssignments()
        {
            using var context = CreateAndSeed();

            var assignments = context.OfficeAssignments.ToList();
            Assert.Equal(3, assignments.Count);
            Assert.Contains(assignments, o => o.Location == "Smith 17");
            Assert.Contains(assignments, o => o.Location == "Gowan 27");
            Assert.Contains(assignments, o => o.Location == "Thompson 304");
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsCourseAssignments()
        {
            using var context = CreateAndSeed();

            var courseAssignments = context.CourseAssignments.ToList();
            Assert.Equal(8, courseAssignments.Count);
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsEnrollments()
        {
            using var context = CreateAndSeed();

            var enrollments = context.Enrollments.ToList();
            Assert.Equal(11, enrollments.Count);
        }

        [Fact]
        public void Initialize_AlreadySeeded_DoesNotDuplicate()
        {
            using var context = CreateAndSeed();

            // Call Initialize a second time
            DbInitializer.Initialize(context);

            Assert.Equal(8, context.Students.Count());
            Assert.Equal(5, context.Instructors.Count());
            Assert.Equal(4, context.Departments.Count());
            Assert.Equal(7, context.Courses.Count());
            Assert.Equal(3, context.OfficeAssignments.Count());
            Assert.Equal(8, context.CourseAssignments.Count());
            Assert.Equal(11, context.Enrollments.Count());
        }

        [Fact]
        public void Initialize_SetsCorrectRelationships()
        {
            using var context = CreateAndSeed();

            var english = context.Departments.Single(d => d.Name == "English");
            var math = context.Departments.Single(d => d.Name == "Mathematics");
            var engineering = context.Departments.Single(d => d.Name == "Engineering");
            var economics = context.Departments.Single(d => d.Name == "Economics");

            var abercrombie = context.Instructors.Single(i => i.LastName == "Abercrombie");
            var fakhouri = context.Instructors.Single(i => i.LastName == "Fakhouri");
            var harui = context.Instructors.Single(i => i.LastName == "Harui");
            var kapoor = context.Instructors.Single(i => i.LastName == "Kapoor");

            Assert.Equal(abercrombie.ID, english.InstructorID);
            Assert.Equal(fakhouri.ID, math.InstructorID);
            Assert.Equal(harui.ID, engineering.InstructorID);
            Assert.Equal(kapoor.ID, economics.InstructorID);
        }

        [Fact]
        public void Initialize_EnrollmentsHaveCorrectGrades()
        {
            using var context = CreateAndSeed();

            var alexander = context.Students.Single(s => s.LastName == "Alexander");
            var anand = context.Students.Single(s => s.LastName == "Anand");

            var enrollments = context.Enrollments.ToList();

            // Alexander - Chemistry = A
            var alexChem = enrollments.Single(e => e.StudentID == alexander.ID && e.CourseID == 1050);
            Assert.Equal(Grade.A, alexChem.Grade);

            // Alexander - Microeconomics = C
            var alexMicro = enrollments.Single(e => e.StudentID == alexander.ID && e.CourseID == 4022);
            Assert.Equal(Grade.C, alexMicro.Grade);

            // Alexander - Macroeconomics = B
            var alexMacro = enrollments.Single(e => e.StudentID == alexander.ID && e.CourseID == 4041);
            Assert.Equal(Grade.B, alexMacro.Grade);

            // Anand - Chemistry = null (no grade)
            var anandChem = enrollments.Single(e => e.StudentID == anand.ID && e.CourseID == 1050);
            Assert.Null(anandChem.Grade);
        }
    }
}

using ContosoUniversity.Models;

namespace ContosoUniversity.Tests
{
    public class ModelTests
    {
        [Theory]
        [InlineData("Smith", "John", "Smith, John")]
        [InlineData("O'Brien", "Mary", "O'Brien, Mary")]
        [InlineData("Li", "Yan", "Li, Yan")]
        [InlineData("Von Trapp", "Maria", "Von Trapp, Maria")]
        public void FullName_ReturnsLastNameCommaFirstMidName(string lastName, string firstMidName, string expected)
        {
            var student = new Student
            {
                LastName = lastName,
                FirstMidName = firstMidName,
                EnrollmentDate = DateTime.Now
            };

            Assert.Equal(expected, student.FullName);
        }

        [Fact]
        public void FullName_WorksOnInstructor()
        {
            var instructor = new Instructor
            {
                LastName = "Abercrombie",
                FirstMidName = "Kim",
                HireDate = DateTime.Now
            };

            Assert.Equal("Abercrombie, Kim", instructor.FullName);
        }

        [Theory]
        [InlineData(Grade.A, 0)]
        [InlineData(Grade.B, 1)]
        [InlineData(Grade.C, 2)]
        [InlineData(Grade.D, 3)]
        [InlineData(Grade.F, 4)]
        public void Grade_HasExpectedIntegerValues(Grade grade, int expectedValue)
        {
            Assert.Equal(expectedValue, (int)grade);
        }

        [Fact]
        public void Enrollment_Grade_CanBeNull()
        {
            var enrollment = new Enrollment();
            Assert.Null(enrollment.Grade);
        }

        [Fact]
        public void Department_RowVersion_CanBeSetAndRead()
        {
            var department = new Department();
            var rowVersion = new byte[] { 0x00, 0x00, 0x00, 0x01 };

            department.RowVersion = rowVersion;

            Assert.Equal(rowVersion, department.RowVersion);
        }

        [Fact]
        public void Department_RowVersion_DefaultIsNull()
        {
            var department = new Department();
            Assert.Null(department.RowVersion);
        }
    }
}

using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using ContosoUniversity.Tests.Helpers;

namespace ContosoUniversity.Tests
{
    public class TestableBaseController : BaseController
    {
        public TestableBaseController(SchoolContext context) : base(context) { }

        public SchoolContext GetDb() => db;
        public NotificationService GetNotificationService() => notificationService;

        public void TestSendEntityNotification(string entityType, string entityId, EntityOperation operation)
            => SendEntityNotification(entityType, entityId, operation);

        public void TestSendEntityNotification(string entityType, string entityId, string displayName, EntityOperation operation)
            => SendEntityNotification(entityType, entityId, displayName, operation);

        public void TestDispose() => Dispose(true);
    }

    public class BaseControllerTests
    {
        [Fact]
        public void Constructor_SetsDbContext()
        {
            using var context = TestDbContextFactory.Create();
            using var controller = new TestableBaseController(context);

            Assert.Same(context, controller.GetDb());
        }

        [Fact]
        public void Constructor_CreatesNotificationService()
        {
            using var context = TestDbContextFactory.Create();
            using var controller = new TestableBaseController(context);

            Assert.NotNull(controller.GetNotificationService());
            Assert.IsType<NotificationService>(controller.GetNotificationService());
        }

        [Fact]
        public void SendEntityNotification_WithDisplayName_EnqueuesNotification()
        {
            using var context = TestDbContextFactory.Create();
            using var controller = new TestableBaseController(context);

            // Drain any existing notifications from the static queue
            var service = controller.GetNotificationService();
            while (service.ReceiveNotification() != null) { }

            controller.TestSendEntityNotification("Student", "1", "John Doe", EntityOperation.CREATE);

            var notification = service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("1", notification.EntityId);
            Assert.Contains("John Doe", notification.Message);
            Assert.Contains("created", notification.Message);
        }

        [Fact]
        public void SendEntityNotification_WithoutDisplayName_EnqueuesNotification()
        {
            using var context = TestDbContextFactory.Create();
            using var controller = new TestableBaseController(context);

            var service = controller.GetNotificationService();
            while (service.ReceiveNotification() != null) { }

            controller.TestSendEntityNotification("Course", "42", EntityOperation.DELETE);

            var notification = service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Course", notification.EntityType);
            Assert.Equal("42", notification.EntityId);
            Assert.Contains("ID: 42", notification.Message);
            Assert.Contains("deleted", notification.Message);
        }

        [Fact]
        public void SendEntityNotification_CompletesWithoutException()
        {
            using var context = TestDbContextFactory.Create();
            using var controller = new TestableBaseController(context);

            var exception = Record.Exception(() =>
                controller.TestSendEntityNotification("Department", "1", EntityOperation.UPDATE));

            Assert.Null(exception);
        }

        [Fact]
        public void Dispose_DisposesWithoutException()
        {
            var context = TestDbContextFactory.Create();
            var controller = new TestableBaseController(context);

            var exception = Record.Exception(() => controller.TestDispose());

            Assert.Null(exception);
        }
    }
}

