using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using ContosoUniversity.Tests.Helpers;

namespace ContosoUniversity.Tests
{
    public class TestableBaseController : BaseController
    {
        public TestableBaseController(SchoolContext context) : base(context) { }

        public SchoolContext GetDb() => db;
        public NotificationService GetNotificationService() => notificationService;

        public void TestSendEntityNotification(string entityType, string entityId, EntityOperation operation)
            => SendEntityNotification(entityType, entityId, operation);

        public void TestSendEntityNotification(string entityType, string entityId, string displayName, EntityOperation operation)
            => SendEntityNotification(entityType, entityId, displayName, operation);

        public void TestDispose() => Dispose(true);
    }

    public class BaseControllerTests
    {
        [Fact]
        public void Constructor_SetsDbContext()
        {
            using var context = TestDbContextFactory.Create();
            using var controller = new TestableBaseController(context);

            Assert.Same(context, controller.GetDb());
        }

        [Fact]
        public void Constructor_CreatesNotificationService()
        {
            using var context = TestDbContextFactory.Create();
            using var controller = new TestableBaseController(context);

            Assert.NotNull(controller.GetNotificationService());
            Assert.IsType<NotificationService>(controller.GetNotificationService());
        }

        [Fact]
        public void SendEntityNotification_WithDisplayName_EnqueuesNotification()
        {
            using var context = TestDbContextFactory.Create();
            using var controller = new TestableBaseController(context);

            // Drain any existing notifications from the static queue
            var service = controller.GetNotificationService();
            while (service.ReceiveNotification() != null) { }

            controller.TestSendEntityNotification("Student", "1", "John Doe", EntityOperation.CREATE);

            var notification = service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("1", notification.EntityId);
            Assert.Contains("John Doe", notification.Message);
            Assert.Contains("created", notification.Message);
        }

        [Fact]
        public void SendEntityNotification_WithoutDisplayName_EnqueuesNotification()
        {
            using var context = TestDbContextFactory.Create();
            using var controller = new TestableBaseController(context);

            var service = controller.GetNotificationService();
            while (service.ReceiveNotification() != null) { }

            controller.TestSendEntityNotification("Course", "42", EntityOperation.DELETE);

            var notification = service.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Course", notification.EntityType);
            Assert.Equal("42", notification.EntityId);
            Assert.Contains("ID: 42", notification.Message);
            Assert.Contains("deleted", notification.Message);
        }

        [Fact]
        public void SendEntityNotification_CompletesWithoutException()
        {
            using var context = TestDbContextFactory.Create();
            using var controller = new TestableBaseController(context);

            var exception = Record.Exception(() =>
                controller.TestSendEntityNotification("Department", "1", EntityOperation.UPDATE));

            Assert.Null(exception);
        }

        [Fact]
        public void Dispose_DisposesWithoutException()
        {
            var context = TestDbContextFactory.Create();
            var controller = new TestableBaseController(context);

            var exception = Record.Exception(() => controller.TestDispose());

            Assert.Null(exception);
        }
    }
}

