         }

         #region Index

         [Fact]
         public void Index_DefaultSort_ReturnsStudentsOrderedByLastNameAscending()
         {
             SeedDefaultStudents();

             var result = _controller.Index(null, null, null, null) as ViewResult;

             var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result!.Model);
             Assert.Equal(3, model.Count);
             Assert.Equal("Alpha", model[0].LastName);
             Assert.Equal("Miller", model[1].LastName);
             Assert.Equal("Zulu", model[2].LastName);
         }

         [Fact]
         public void Index_NameDescSort_ReturnsStudentsOrderedByLastNameDescending()
         {
             SeedDefaultStudents();

             var result = _controller.Index("name_desc", null, null, null) as ViewResult;

             var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result!.Model);
             Assert.Equal("Zulu", model[0].LastName);
             Assert.Equal("Miller", model[1].LastName);
             Assert.Equal("Alpha", model[2].LastName);
         }

