         {
             SeedDefaultStudents();

             var result = _controller.Index("Date", null, null, null) as ViewResult;

             var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result!.Model);
             Assert.Equal("Alpha", model[0].LastName);   // 2022-06-01
             Assert.Equal("Zulu", model[1].LastName);     // 2023-01-15
             Assert.Equal("Miller", model[2].LastName);   // 2024-03-10
         }

