 namespace ContosoUniversity.Tests
 {
     public class PaginatedListTests
     {
         [Fact]
         public void Constructor_WithItems_SetsPageIndexAndAddsItems()
         {
             // Arrange
             var items = new List<string> { "A", "B", "C" };

             // Act
             var list = new PaginatedList<string>(items, count: 10, pageIndex: 2, pageSize: 3);

             // Assert
             Assert.Equal(2, list.PageIndex);
             Assert.Equal(3, list.Count);
             Assert.Equal("A", list[0]);
             Assert.Equal("B", list[1]);
             Assert.Equal("C", list[2]);
         }

         [Theory]
         [InlineData(10, 3, 4)]   // ceil(10/3) = 4
         [InlineData(10, 5, 2)]   // ceil(10/5) = 2
         [InlineData(1, 5, 1)]    // ceil(1/5)  = 1
         [InlineData(7, 2, 4)]    // ceil(7/2)  = 4
         [InlineData(0, 5, 0)]    // ceil(0/5)  = 0
         public void Constructor_CalculatesTotalPages_Correctly(int count, int pageSize, int expectedTotalPages)
         {
             // Arrange & Act
             var list = new PaginatedList<int>(new List<int>(), count, pageIndex: 1, pageSize);

             // Assert
             Assert.Equal(expectedTotalPages, list.TotalPages);
         }

         [Theory]
         [InlineData(1, false)]   // Page 1 -> no previous
         [InlineData(2, true)]    // Page 2 -> has previous
         [InlineData(5, true)]    // Page 5 -> has previous
         public void HasPreviousPage_ReturnsCorrectly(int pageIndex, bool expected)
         {
             // Arrange & Act
             var list = new PaginatedList<int>(new List<int>(), count: 50, pageIndex, pageSize: 10);

             // Assert
             Assert.Equal(expected, list.HasPreviousPage);
         }

         [Theory]
         [InlineData(1, 5, true)]    // Page 1 of 5 -> has next
         [InlineData(5, 5, false)]   // Page 5 of 5 -> no next
         [InlineData(3, 5, true)]    // Page 3 of 5 -> has next
         public void HasNextPage_ReturnsCorrectly(int pageIndex, int totalPages, bool expected)
         {
             // Arrange - count and pageSize chosen so TotalPages = totalPages
             var list = new PaginatedList<int>(new List<int>(), count: totalPages * 10, pageIndex, pageSize: 10);

             // Assert
             Assert.Equal(expected, list.HasNextPage);
         }

         [Fact]
         public void HasPreviousPage_PageOneOfOne_ReturnsFalse()
         {
             // Arrange
             var list = new PaginatedList<string>(new List<string> { "only" }, count: 1, pageIndex: 1, pageSize: 10);

