 using ContosoUniversity.Tests.Helpers;
 using Microsoft.AspNetCore.Http;
 using Microsoft.AspNetCore.Mvc;
 using Microsoft.AspNetCore.Mvc.ViewFeatures;
 using Moq;
 using Xunit;

 namespace ContosoUniversity.Tests
 {
     public class StudentsControllerTests : IDisposable
     {
         private readonly SchoolContext _context;
         private readonly StudentsController _controller;

         public StudentsControllerTests()
         {
             _context = TestDbContextFactory.Create();
             _controller = CreateController(_context);
         }

         public void Dispose()
         {
             _controller.Dispose();
             _context.Dispose();
         }

         private static StudentsController CreateController(SchoolContext context)
         {
             var controller = new StudentsController(context);
             controller.ControllerContext = new ControllerContext
             {
                 HttpContext = new DefaultHttpContext()
             };
             var tempDataProvider = new Mock<ITempDataProvider>();
             tempDataProvider
                 .Setup(p => p.LoadTempData(It.IsAny<HttpContext>()))
                 .Returns(new Dictionary<string, object?>());
             controller.TempData = new TempDataDictionary(
                 controller.ControllerContext.HttpContext,
                 tempDataProvider.Object);
             return controller;
         }

         private void SeedStudents(params Student[] students)
         {
             _context.Students.AddRange(students);
             _context.SaveChanges();
         }

         private Student MakeStudent(string last, string first, DateTime enrollment)
         {
             return new Student
             {
                 LastName = last,
                 FirstMidName = first,
                 EnrollmentDate = enrollment
             };
         }

         private void SeedDefaultStudents()
         {
             SeedStudents(
                 MakeStudent("Zulu", "Alice", new DateTime(2023, 1, 15)),
                 MakeStudent("Alpha", "Bob", new DateTime(2022, 6, 1)),
                 MakeStudent("Miller", "Charlie", new DateTime(2024, 3, 10))
             );
         }

         #region Index

         [Fact]
         public void Index_DefaultSort_ReturnsStudentsOrderedByLastNameAscending()
         {
             SeedDefaultStudents();

             var result = _controller.Index(null, null, null, null) as ViewResult;

             var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result!.Model);
             Assert.Equal(3, model.Count);
             Assert.Equal("Alpha", model[0].LastName);
             Assert.Equal("Miller", model[1].LastName);
             Assert.Equal("Zulu", model[2].LastName);
         }

         [Fact]
         public void Index_NameDescSort_ReturnsStudentsOrderedByLastNameDescending()
         {
             SeedDefaultStudents();

             var result = _controller.Index("name_desc", null, null, null) as ViewResult;

             var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result!.Model);
             Assert.Equal("Zulu", model[0].LastName);
             Assert.Equal("Miller", model[1].LastName);
             Assert.Equal("Alpha", model[2].LastName);
         }

         [Fact]
         public void Index_DateSort_ReturnsStudentsOrderedByEnrollmentDateAscending()
         {
             SeedDefaultStudents();

             var result = _controller.Index("Date", null, null, null) as ViewResult;

             var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result!.Model);
             Assert.Equal("Alpha", model[0].LastName);   // 2022-06-01
             Assert.Equal("Zulu", model[1].LastName);     // 2023-01-15
             Assert.Equal("Miller", model[2].LastName);   // 2024-03-10
         }

         [Fact]
         public void Index_DateDescSort_ReturnsStudentsOrderedByEnrollmentDateDescending()
         {
             SeedDefaultStudents();

             var result = _controller.Index("date_desc", null, null, null) as ViewResult;

             var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result!.Model);
             Assert.Equal("Miller", model[0].LastName);   // 2024-03-10
             Assert.Equal("Zulu", model[1].LastName);     // 2023-01-15
             Assert.Equal("Alpha", model[2].LastName);    // 2022-06-01
         }

         [Theory]
         [InlineData("Alice", 1, "Zulu")]
         [InlineData("Alpha", 1, "Alpha")]
         [InlineData("li", 2, null)] // matches Alice (FirstMidName) and Miller (neither, but "li" in Charlie? Actually "li" in Alice and "lli" in Miller)
         public void Index_SearchString_FiltersStudentsByLastNameOrFirstMidName(string search, int expectedCount, string? expectedFirstLastName)
         {
             SeedDefaultStudents();

             var result = _controller.Index(null, null, search, null) as ViewResult;

             var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result!.Model);
             Assert.Equal(expectedCount, model.Count);
             if (expectedFirstLastName != null)
             {
                 Assert.Equal(expectedFirstLastName, model[0].LastName);
             }
         }

         [Fact]
         public void Index_SearchStringNotNull_ResetsPageToOne()
         {
             // Seed enough students so page 2 would exist
             for (int i = 0; i < 15; i++)
             {
                 SeedStudents(MakeStudent($"Student{i:D2}", "Test", new DateTime(2023, 1, 1)));
             }

             // Pass page=2 but with a new searchString; controller resets page to 1
             var result = _controller.Index(null, null, "Student", 2) as ViewResult;

             var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result!.Model);
             Assert.Equal(1, model.PageIndex);
         }

         [Fact]
         public void Index_SearchStringNull_UsesCurrentFilter()
         {
             SeedDefaultStudents();

             var result = _controller.Index(null, "Alpha", null, null) as ViewResult;

             var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result!.Model);
             Assert.Single(model);
             Assert.Equal("Alpha", model[0].LastName);
         }

         [Fact]
         public void Index_SetsViewBagProperties()
         {
             SeedDefaultStudents();

             var result = _controller.Index("Date", null, "test", null) as ViewResult;

             Assert.Equal("Date", _controller.ViewBag.CurrentSort);
             Assert.Equal("date_desc", _controller.ViewBag.DateSortParm);
             Assert.Equal("", _controller.ViewBag.NameSortParm);
             Assert.Equal("test", _controller.ViewBag.CurrentFilter);
         }

         [Fact]
         public void Index_DefaultSortOrder_SetsNameSortParmToNameDesc()
         {
             var result = _controller.Index(null, null, null, null) as ViewResult;

             Assert.Equal("name_desc", _controller.ViewBag.NameSortParm);
             Assert.Equal("Date", _controller.ViewBag.DateSortParm);
         }

         [Fact]
         public void Index_Pagination_LimitsToTenPerPage()
         {
             for (int i = 0; i < 12; i++)
             {
                 SeedStudents(MakeStudent($"Student{i:D2}", "Test", new DateTime(2023, 1, 1)));
             }

             var result = _controller.Index(null, null, null, 1) as ViewResult;

             var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result!.Model);
             Assert.Equal(10, model.Count);
             Assert.Equal(1, model.PageIndex);
             Assert.Equal(2, model.TotalPages);
             Assert.True(model.HasNextPage);
             Assert.False(model.HasPreviousPage);
         }

         [Fact]
         public void Index_Page2_ReturnsRemainingStudents()
         {
             for (int i = 0; i < 12; i++)
             {
                 SeedStudents(MakeStudent($"Student{i:D2}", "Test", new DateTime(2023, 1, 1)));
             }

             var result = _controller.Index(null, null, null, 2) as ViewResult;

             var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result!.Model);
             Assert.Equal(2, model.Count);
             Assert.Equal(2, model.PageIndex);
             Assert.True(model.HasPreviousPage);
             Assert.False(model.HasNextPage);
         }

         #endregion

         #region Details

         [Fact]
         public void Details_IdIsNull_ReturnsBadRequest()
         {
             var result = _controller.Details(null);

             var statusResult = Assert.IsType<StatusCodeResult>(result);
             Assert.Equal(400, statusResult.StatusCode);
         }

         [Fact]
         public void Details_StudentExists_ReturnsViewWithStudent()
         {
             var student = MakeStudent("Smith", "Jane", new DateTime(2023, 5, 1));
             SeedStudents(student);

             var result = _controller.Details(student.ID) as ViewResult;

             var model = Assert.IsType<Student>(result!.Model);
             Assert.Equal("Smith", model.LastName);
             Assert.Equal("Jane", model.FirstMidName);
         }

         [Fact]
         public void Details_StudentExists_IncludesEnrollments()
         {
             var student = MakeStudent("Smith", "Jane", new DateTime(2023, 5, 1));
             SeedStudents(student);
             var dept = new Department { Name = "CS", Budget = 1000, StartDate = DateTime.Now };
             _context.Departments.Add(dept);
             _context.SaveChanges();
             var course = new Course { CourseID = 101, Title = "Intro", Credits = 3, DepartmentID = dept.DepartmentID };
             _context.Courses.Add(course);
             _context.SaveChanges();
             _context.Enrollments.Add(new Enrollment { StudentID = student.ID, CourseID = 101, Grade = Grade.A });
             _context.SaveChanges();

             var result = _controller.Details(student.ID) as ViewResult;

             var model = Assert.IsType<Student>(result!.Model);
             Assert.Single(model.Enrollments);
             Assert.Equal(Grade.A, model.Enrollments.First().Grade);
         }

         [Fact]
         public void Details_StudentNotFound_ThrowsInvalidOperationException()
         {
             Assert.Throws<InvalidOperationException>(() => _controller.Details(9999));
         }

         #endregion

         #region Create GET

         [Fact]
         public void Create_Get_ReturnsViewWithStudentHavingTodayDate()
         {
             var result = _controller.Create() as ViewResult;

             var model = Assert.IsType<Student>(result!.Model);
             Assert.Equal(DateTime.Today, model.EnrollmentDate);
         }

         #endregion

         #region Create POST

         [Fact]
         public void Create_Post_ValidStudent_AddsAndRedirectsToIndex()
         {
             var student = MakeStudent("Doe", "John", new DateTime(2023, 9, 1));

             var result = _controller.Create(student);

             var redirect = Assert.IsType<RedirectToActionResult>(result);
             Assert.Equal("Index", redirect.ActionName);
             Assert.Single(_context.Students);
             Assert.Equal("Doe", _context.Students.First().LastName);
         }

         [Fact]
         public void Create_Post_MinValueDate_AddsModelErrorAndReturnsView()
         {
             var student = MakeStudent("Doe", "John", DateTime.MinValue);

             var result = _controller.Create(student) as ViewResult;

             Assert.NotNull(result);
             Assert.False(_controller.ModelState.IsValid);
             Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
         }

         [Fact]
         public void Create_Post_DateBefore1753_AddsModelErrorAndReturnsView()
         {
             var student = MakeStudent("Doe", "John", new DateTime(1000, 1, 1));

             var result = _controller.Create(student) as ViewResult;

             Assert.NotNull(result);
             Assert.False(_controller.ModelState.IsValid);
             Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
         }

         [Fact]
         public void Create_Post_InvalidModelState_ReturnsViewWithStudent()
         {
             var student = MakeStudent("Doe", "John", new DateTime(2023, 9, 1));
             _controller.ModelState.AddModelError("LastName", "Required");

             var result = _controller.Create(student) as ViewResult;

             Assert.NotNull(result);
             var model = Assert.IsType<Student>(result!.Model);
             Assert.Equal("Doe", model.LastName);
             Assert.Empty(_context.Students);
         }

         [Fact]
         public void Create_Post_ValidStudent_SendsNotification()
         {
             var student = MakeStudent("Doe", "John", new DateTime(2023, 9, 1));

             _controller.Create(student);

             // Notification was sent; we can verify by accessing the notificationService
             // through the controller. Since it uses a static queue, drain and check.
             var notifController = new NotificationsController(_context);
             notifController.ControllerContext = new ControllerContext
             {
                 HttpContext = new DefaultHttpContext()
             };
             var json = notifController.GetNotifications();
             var value = json.Value;
             var successProp = value!.GetType().GetProperty("success")!.GetValue(value);
             var countProp = value.GetType().GetProperty("count")!.GetValue(value);
             Assert.True((bool)successProp!);
             Assert.True((int)countProp! >= 1);
             notifController.Dispose();
         }

         #endregion

         #region Edit GET

         [Fact]
         public void Edit_Get_IdIsNull_ReturnsBadRequest()
         {
             var result = _controller.Edit((int?)null);

             var statusResult = Assert.IsType<StatusCodeResult>(result);
             Assert.Equal(400, statusResult.StatusCode);
         }

         [Fact]
         public void Edit_Get_StudentNotFound_ReturnsNotFound()
         {
             var result = _controller.Edit(9999);

             Assert.IsType<NotFoundResult>(result);
         }

         [Fact]
         public void Edit_Get_StudentExists_ReturnsViewWithStudent()
         {
             var student = MakeStudent("Smith", "Jane", new DateTime(2023, 5, 1));
             SeedStudents(student);

             var result = _controller.Edit(student.ID) as ViewResult;

             var model = Assert.IsType<Student>(result!.Model);
             Assert.Equal("Smith", model.LastName);
         }

         #endregion

         #region Edit POST

         [Fact]
         public void Edit_Post_ValidStudent_UpdatesAndRedirectsToIndex()
         {
             var student = MakeStudent("Smith", "Jane", new DateTime(2023, 5, 1));
             SeedStudents(student);

             // Detach to simulate a form post with a new tracked entity
             _context.Entry(student).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

             var editedStudent = new Student
             {
                 ID = student.ID,
                 LastName = "SmithUpdated",
                 FirstMidName = "Jane",
                 EnrollmentDate = new DateTime(2023, 5, 1)
             };

             var result = _controller.Edit(editedStudent);

             var redirect = Assert.IsType<RedirectToActionResult>(result);
             Assert.Equal("Index", redirect.ActionName);
         }

         [Fact]
         public void Edit_Post_MinValueDate_AddsModelError()
         {
             var student = new Student
             {
                 ID = 1,
                 LastName = "Doe",
                 FirstMidName = "John",
                 EnrollmentDate = DateTime.MinValue
             };

             var result = _controller.Edit(student) as ViewResult;

             Assert.NotNull(result);
             Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
         }

         [Fact]
         public void Edit_Post_DateBefore1753_AddsModelError()
         {
             var student = new Student
             {
                 ID = 1,
                 LastName = "Doe",
                 FirstMidName = "John",
                 EnrollmentDate = new DateTime(1000, 1, 1)
             };

             var result = _controller.Edit(student) as ViewResult;

             Assert.NotNull(result);
             Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
         }

         [Fact]
         public void Edit_Post_InvalidModelState_ReturnsViewWithStudent()
         {
             var student = MakeStudent("Doe", "John", new DateTime(2023, 9, 1));
             _controller.ModelState.AddModelError("LastName", "Required");

             var result = _controller.Edit(student) as ViewResult;

             Assert.NotNull(result);
             var model = Assert.IsType<Student>(result!.Model);
             Assert.Equal("Doe", model.LastName);
         }

         #endregion

         #region Delete GET

         [Fact]
         public void Delete_Get_IdIsNull_ReturnsBadRequest()
         {
             var result = _controller.Delete(null);

             var statusResult = Assert.IsType<StatusCodeResult>(result);
             Assert.Equal(400, statusResult.StatusCode);
         }

         [Fact]
         public void Delete_Get_StudentNotFound_ReturnsNotFound()
         {
             var result = _controller.Delete(9999);

             Assert.IsType<NotFoundResult>(result);
         }

         [Fact]
         public void Delete_Get_StudentExists_ReturnsViewWithStudent()
         {
             var student = MakeStudent("Smith", "Jane", new DateTime(2023, 5, 1));
             SeedStudents(student);

             var result = _controller.Delete(student.ID) as ViewResult;

             var model = Assert.IsType<Student>(result!.Model);
             Assert.Equal("Smith", model.LastName);
         }

         #endregion

         #region DeleteConfirmed

         [Fact]
         public void DeleteConfirmed_StudentExists_RemovesAndRedirectsToIndex()
         {
             var student = MakeStudent("Smith", "Jane", new DateTime(2023, 5, 1));
             SeedStudents(student);

             var result = _controller.DeleteConfirmed(student.ID);

             var redirect = Assert.IsType<RedirectToActionResult>(result);
             Assert.Equal("Index", redirect.ActionName);
             Assert.Empty(_context.Students);
         }

         [Fact]
         public void DeleteConfirmed_StudentNotFound_SetsTempDataErrorAndRedirects()
         {
             // Find with nonexistent ID will return null, causing NullReferenceException caught by catch
             var result = _controller.DeleteConfirmed(9999);

             var redirect = Assert.IsType<RedirectToActionResult>(result);
             Assert.Equal("Index", redirect.ActionName);
             Assert.NotNull(_controller.TempData["ErrorMessage"]);
             Assert.Contains("Unable to delete", _controller.TempData["ErrorMessage"]!.ToString());
         }

         #endregion
     }


 }

