    // Track the same entity with a different instance to cause a tracking conflict on SaveChanges
    var conflicting = new Student
    {
        ID = student.ID,
        LastName = "SmithEdited",
        FirstMidName = "Jane",
        EnrollmentDate = new DateTime(2023, 5, 1)
    };

    // The entity is already tracked, so setting Modified on a second instance will throw
    var result = _controller.Edit(conflicting) as ViewResult;

    Assert.NotNull(result);
    Assert.False(_controller.ModelState.IsValid);
    var errors = _controller.ModelState[""]?.Errors;
    Assert.NotNull(errors);
    Assert.Contains(errors, e => e.ErrorMessage.Contains("Unable to save changes"));
}

